#!/usr/bin/env bash
# Oblada's edits to Chromium's own files are kept as one patch per file in chromium/patches/
# (Brave's layout: when a Chromium update conflicts, exactly one small patch needs fixing).
# New files never go into Chromium's tree: they live in chromium/oblada, linked as src/oblada.
# The "Chromium" -> "Oblada" string renaming is generated by rebrand.py instead of patched
# (it touches ~250 translation files), so those files are left out of the patches.
# Images can't be patched: the logo files (made by branding/export.sh) sit in
# chromium/overrides at their paths in src and are copied over Chromium's own.
#
#   patches.sh apply    link src/oblada, apply every patch that isn't applied yet, copy the
#                       overrides, rebrand
#   patches.sh update   rewrite chromium/patches/ from what is modified in src right now
#   patches.sh reset    revert the patched and rebranded files (before moving to a new version)
set -euo pipefail
source "$(dirname "$0")/env.sh"
shopt -s nullglob

REBRANDED='chromium_strings'

overridden_files() {
  (cd "$HERE/overrides" && find . -type f ! -name .DS_Store | sed 's|^\./||')
}

patched_files() {
  for p in "$HERE"/patches/*.patch; do sed -n 's|^+++ b/||p' "$p"; done
  overridden_files
  git -C "$SRC" diff HEAD --name-only | grep "$REBRANDED" || true
}

case "${1:-apply}" in
  apply)
    ln -sfn "$HERE/oblada" "$SRC/oblada"
    for p in "$HERE"/patches/*.patch; do
      if git -C "$SRC" apply --check --reverse "$p" 2>/dev/null; then continue; fi
      git -C "$SRC" apply --3way "$p" || { echo "patch does not apply: $p" >&2; exit 1; }
    done
    overridden_files | while read -r f; do
      cmp -s "$HERE/overrides/$f" "$SRC/$f" || cp "$HERE/overrides/$f" "$SRC/$f"
    done
    python3 "$HERE/scripts/rebrand.py" "$SRC" | wc -l | xargs echo "rebranded files:"
    ;;
  update)
    rm -f "$HERE"/patches/*.patch
    git -C "$SRC" diff HEAD --name-only | grep -v "$REBRANDED" | grep -vxF -f <(overridden_files) |
    while read -r f; do
      git -C "$SRC" diff HEAD -- "$f" > "$HERE/patches/${f//\//-}.patch"
    done
    ls "$HERE/patches"
    ;;
  reset)
    patched_files | while read -r f; do git -C "$SRC" checkout HEAD -- "$f" 2>/dev/null || true; done
    ;;
  *)
    echo "usage: patches.sh apply|update|reset" >&2
    exit 2
    ;;
esac
